### ✅ Program in C++ to find the **n-th** number in this sequence:

```cpp
#include <iostream>

// Function to compute the n-th term in the Triplet Fibonacci sequence
unsigned long long tripletFibonacci(unsigned long long n) {
    if (n == 0) return 0;
    if (n == 1 || n == 2) return -1;

    // Initialize the first three terms
    unsigned long long a = 0, b = -1, c = -1;

    for (unsigned long long i = 3; i <= n; ++i) {
        unsigned long long next = a + b + c;
        a = b;
        b = c;
        c = next;
    }

    return c;
}

int main() {
    unsigned long long n;

    std::cout << "Enter the position (n) of the Fibonacci number: ";
    std::cin >> n;

    if (n < 0) {
        std::cerr << "Error: Invalid input. Please enter a non-negative integer." << std::endl;
        return 1;
    }

    unsigned long long result = tripletFibonacci(n);
    std::cout << "The " << n << "-th Triplet Fibonacci number is: " << result << std::endl;

    return 0;
}
```

---

